package org.example.saildroid.media;
import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.graphics.SurfaceTexture;import android.view.*;import android.widget.*;import android.media.MediaPlayer;import java.io.*;
public final class MediaActivity extends Activity implements TextureView.SurfaceTextureListener {
 final Handler handler=new Handler();MediaPlayer player;Surface surface;FileInputStream input;TextView status;int stage=0;long paused;boolean rendered=false;long maxPosition;int seeks;
 void log(String text){System.err.println("MEDIA_PROBE="+text);if(status!=null)status.setText(text);}
 public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout box=new LinearLayout(this);box.setOrientation(1);status=new TextView(this);status.setTextSize(18);box.addView(status,new LinearLayout.LayoutParams(-1,160));TextureView texture=new TextureView(this);texture.setSurfaceTextureListener(this);box.addView(texture,new LinearLayout.LayoutParams(-1,1100));Button pause=new Button(this);pause.setText("Pause / resume");pause.setOnClickListener(v->{if(player!=null){if(player.isPlaying())player.pause();else player.start();log("touch|playing="+player.isPlaying());}});box.addView(pause,new LinearLayout.LayoutParams(-1,150));setContentView(box);log("created");}
 public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){try{
  File media=new File(getFilesDir(),"bounded-video.bin");try(InputStream in=getAssets().open("clip.webm");FileOutputStream out=new FileOutputStream(media)){out.write(new byte[37]);byte[]b=new byte[65536];int n;while((n=in.read(b))>0)out.write(b,0,n);out.write(new byte[91]);}
  input=new FileInputStream(media);player=new MediaPlayer();surface=new Surface(t);player.setSurface(surface);player.setOnErrorListener((mp,a,b)->{log("error|what="+a+"|extra="+b);return true;});player.setOnVideoSizeChangedListener((mp,x,y)->log("size|w="+x+"|h="+y));player.setOnInfoListener((mp,a,b)->{log("info|what="+a+"|extra="+b);if(a==3)rendered=true;return true;});player.setOnPreparedListener(mp->{log("prepared|duration="+mp.getDuration()+"|width="+mp.getVideoWidth()+"|height="+mp.getVideoHeight());mp.start();handler.postDelayed(this::tick,1200);});player.setOnSeekCompleteListener(mp->{seeks++;log("seek_complete|position="+mp.getCurrentPosition());if(stage==2){stage=3;mp.start();}});player.setOnCompletionListener(mp->log("complete|position="+mp.getCurrentPosition()+"|max="+maxPosition+"|rendered="+rendered+"|seeks="+seeks));player.setDataSource(input.getFD(),37,media.length()-128);player.prepareAsync();log("prepare_requested|offset=37|trailer=91");
 }catch(Throwable ex){log("exception|"+ex);ex.printStackTrace();}}
 void tick(){try{long now=player.getCurrentPosition();maxPosition=Math.max(maxPosition,now);log("progress|position="+now+"|playing="+player.isPlaying()+"|stage="+stage);if(stage==0){if(now<500)throw new AssertionError("No playback progress");player.pause();paused=player.getCurrentPosition();stage=1;handler.postDelayed(this::tick,900);}else if(stage==1){if(Math.abs(now-paused)>150)throw new AssertionError("Pause did not stop clock");log("pause_pass|before="+paused+"|after="+now);stage=2;player.seekTo(3500,MediaPlayer.SEEK_CLOSEST);handler.postDelayed(this::tick,1300);}else if(stage>=2&&now<5800)handler.postDelayed(this::tick,700);}catch(Throwable ex){log("exception|"+ex);ex.printStackTrace();}}
 public boolean onSurfaceTextureDestroyed(SurfaceTexture t){if(player!=null){player.release();player=null;}if(surface!=null)surface.release();try{if(input!=null)input.close();}catch(IOException ignored){}return true;}
 public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){}public void onSurfaceTextureUpdated(SurfaceTexture t){}
}
